class Solution {
public:
    std::vector<long long> minOperations(std::vector<int>& nums, std::vector<int>& queries) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        std::vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
        std::vector<long long> ans;
        ans.reserve(queries.size());
        for (int q : queries) {
            auto it = std::lower_bound(nums.begin(), nums.end(), q);
            long long idx = it - nums.begin();
            long long left_cost = idx * q - pref[idx];
            long long right_cost = (pref[n] - pref[idx]) - (n - idx) * q;
            ans.push_back(left_cost + right_cost);
        }
        return ans;
    }
};

class Solution {
    public java.util.List<Long> minOperations(int[] nums, int[] queries) {
        java.util.Arrays.sort(nums);
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        java.util.List<Long> ans = new java.util.ArrayList<>();
        for (int q : queries) {
            int idx = java.util.Arrays.binarySearch(nums, q);
            if (idx < 0) idx = -(idx + 1);
            else {
                while (idx > 0 && nums[idx - 1] == q) idx--;
            }
            long leftCost = (long) idx * q - pref[idx];
            long rightCost = (pref[n] - pref[idx]) - (long) (n - idx) * q;
            ans.add(leftCost + rightCost);
        }
        return ans;
    }
}

var minOperations = function(nums, queries) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const pref = new BigInt64Array(n + 1);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + BigInt(nums[i]);
    const ans = [];
    for (const q of queries) {
        const bq = BigInt(q);
        let low = 0, high = n;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (nums[mid] < q) low = mid + 1;
            else high = mid;
        }
        const idx = BigInt(low);
        const leftCost = idx * bq - pref[low];
        const rightCost = (pref[n] - pref[low]) - (BigInt(n) - idx) * bq;
        ans.push(Number(leftCost + rightCost));
    }
    return ans;
};
